// 方案 A: 使用 zgees (Schur 分解, evals 按实部降序)
zgees_('V', 'N', nullptr, &n_dim, W_copy.data(), &n_dim,
         &s_dim, evals_ordered.data(), ...);

// 方案 B: zgeev + 字典序排序 + evec 相位固定
zgeev_(..., evals.data(), VR.data(), ...);
// 1. evals 按 (Re desc, Im desc) 排序
std::sort(perm.begin(), perm.end(), [&](int a, int b) {
    if (std::abs(evals[a].real() - evals[b].real()) > 1e-12)
        return evals[a].real() > evals[b].real();
    return evals[a].imag() > evals[b].imag();
});
// 2. evec 相位固定: 令最大分量为正实数
for (int n = 0; n < n_dim; ++n) {
    int max_idx = argmax(|VR[:,n]|);
    complex phase = VR[max_idx, n] / |VR[max_idx, n]|;
    VR[:, n] /= phase;
}

for (int n = 0; n < n_dim; ++n) {
    double best_diff = 1e10;
    int best_m = -1;
    for (int m = 0; m < n_dim; ++m) {
        if (matched[m]) continue;
        double diff = std::arg(evals_j[n] / evals_prev[m]);
        // wrap to (-π, π]
        if (diff > M_PI) diff -= 2*M_PI;
        if (diff <= -M_PI) diff += 2*M_PI;
        if (std::abs(diff) < best_diff) {
            best_diff = std::abs(diff);
            best_m = m;
        }
    }
    // 贪心: 第一个 n 选走最优 m, 后面的 n 可能被迫选次优
    matched[best_m] = true;
    gamma_new[best_m] = gamma_unwrapped[best_m] + diff;
}

// 构建代价矩阵
std::vector<std::vector<double>> cost(n_dim, std::vector<double>(n_dim));
for (int i = 0; i < n_dim; ++i)
    for (int j = 0; j < n_dim; ++j) {
        double diff = std::arg(evals_new[i] / evals_prev[j]);
        if (diff > M_PI) diff -= 2*M_PI;
        if (diff <= -M_PI) diff += 2*M_PI;
        cost[i][j] = std::abs(diff);
    }

// 匈牙利算法求最小权匹配
std::vector<int> assignment = hungarian(cost);

// 应用匹配
for (int i = 0; i < n_dim; ++i) {
    int j = assignment[i];  // 新 eval i 匹配前驱 j
    double diff = std::arg(evals_new[i] / evals_prev[j]);
    if (diff > M_PI) diff -= 2*M_PI;
    if (diff <= -M_PI) diff += 2*M_PI;
    gamma_new[j] = gamma_unwrapped[j] + diff;
}

// 第一条 k-string: 正常计算, 存储结果为参考
std::vector<double> gamma_ref(nat_, 0.0);
for (int istring = 0; istring < total_string_; ++istring) {
    // ... 计算 gamma_I_per_atom[iat] ...

    if (istring == 0) {
        gamma_ref = gamma_I_per_atom;
    } else {
        // 后续 string: 对每个原子, 选最接近 ref 的分支
        for (int iat = 0; iat < nat_; ++iat) {
            double g = gamma_I_per_atom[iat];
            double ref = gamma_ref[iat];
            // 搜索 k = -3..+3
            double best_val = g;
            double best_dist = 1e10;
            for (int k = -3; k <= 3; ++k) {
                double candidate = g + k * 2.0 * M_PI * smo_weight_sum[iat] / n_dim;
                double dist = std::abs(candidate - ref);
                if (dist < best_dist) {
                    best_dist = dist;
                    best_val = candidate;
                }
            }
            gamma_I_per_atom[iat] = best_val;
        }
    }
    // 累加到 gamma_accum
}
